INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT349','S115','Gia hạn gói cước SIM khi hết hạn',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V349','SIT349','P1','twist','ban_chinh_thuc',NULL,'国内手机运营商会推出专属学生优惠套餐，优惠到期或活动结束就无法办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_01','V349','阮明',1,'您好，我的手机流量套餐今天到期，想现场续费。','nín hǎo， wǒ de shǒu jī liú liàng tào cān jīn tiān dào qī， xiǎng xiàn chǎng xù fèi。','Chào chị, gói cước data của em hôm nay hết hạn, em muốn gia hạn luôn tại đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_02','V349','工作人员',2,'可以，出示手机卡号，我帮你查询套餐选项。','kě yǐ， chū shì shǒu jī kǎ hào， wǒ bāng nǐ chá xún tào cān xuǎn xiàng。','Được em, em cho chị xem số thuê bao để chị kiểm tra các gói cước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_03','V349','阮明',3,'我平时流量用得多，有没有不限流量的学生套餐？','wǒ píng shí liú liàng yòng dé duō， yǒu méi yǒu bù xiàn liú liàng de xué shēng tào cān？','Em dùng data khá nhiều, có gói sinh viên không giới hạn dung lượng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_04','V349','工作人员',4,'学生专属套餐本月已经下架，只能选普通套餐嘛。','xué shēng zhuān shǔ tào cān běn yuè yǐ jīng xià jià， zhǐ néng xuǎn pǔ tōng tào cān ma。','Gói dành riêng cho sinh viên tháng này ngừng bán rồi, chỉ còn gói thường thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_05','V349','阮明',5,'啊，那普通套餐每月多少流量，多少钱月租？','a， nà pǔ tōng tào cān měi yuè duō shǎo liú liàng， duō shǎo qián yuè zū？','À vậy gói thường mỗi tháng bao nhiêu dung lượng, cước tháng bao nhiêu ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_06','V349','工作人员',6,'每月40G流量，月租三十九元，性价比很高。','měi yuè 40G liú liàng， yuè zū sān shí jiǔ yuán， xìng jià bǐ hěn gāo。','Mỗi tháng 40G data, cước tháng ba mươi chín tệ, rất đáng tiền đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_07','V349','阮明',7,'行，那就办理这个普通套餐续费吧。','xíng， nà jiù bàn lǐ zhè ge pǔ tōng tào cān xù fèi ba。','Dạ được, vậy chị làm gia hạn gói thường này cho em nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT350','S116','Nhờ sửa lỗi kết nối wifi trong phòng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V350','SIT350','P1','suon_se','ban_chinh_thuc',NULL,'宽带套餐保修期内，线路、WiFi故障可免费上门维修，无需支付人工费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_01','V350','阮明',1,'师傅，我房间WiFi突然连不上了，麻烦上门看看吧。','shī fù， wǒ fáng jiān WiFi tū rán lián bù shàng le， má fán shàng mén kàn kàn ba。','Chú ơi, WiFi phòng cháu tự nhiên không kết nối được, phiền chú đến xem giúp cháu với.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_02','V350','维修师傅',2,'好，我先检查光猫和路由器，大概率是线路松动。','hǎo， wǒ xiān jiǎn chá guāng māo hé lù yóu qì， dà gài lǜ shì xiàn lù sōng dòng。','Được, chú kiểm tra modem quang với router trước đã, khả năng cao là dây bị lỏng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_03','V350','阮明',3,'昨天网络还很流畅，今天一早直接断网了呢。','zuó tiān wǎng luò hái hěn liú chàng， jīn tiān yī zǎo zhí jiē duàn wǎng le ne。','Hôm qua mạng còn chạy êm ru, sáng nay tự dưng mất kết nối luôn ấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_04','V350','维修师傅',4,'我重新插紧线路，再重置路由器就能恢复。','wǒ chóng xīn chā jǐn xiàn lù， zài zhòng zhì lù yóu qì jiù néng huī fù。','Chú cắm chặt lại dây, rồi reset router là dùng lại được ngay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_05','V350','阮明',5,'维修需要额外收取服务费吗？','wéi xiū xū yào é wài shōu qǔ fú wù fèi ma？','Sửa vậy có tính thêm phí dịch vụ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_06','V350','维修师傅',6,'在宽带保修期内，上门检修完全免费。','zài kuān dài bǎo xiū qī nèi， shàng mén jiǎn xiū wán quán miǎn fèi。','Còn trong thời hạn bảo hành mạng thì đến kiểm tra sửa hoàn toàn miễn phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_07','V350','阮明',7,'太好了，辛苦师傅帮忙处理啦。','tài hǎo le， xīn kǔ shī fù bāng máng chǔ lǐ la。','Tuyệt quá, cảm ơn chú đã giúp đỡ nhiều nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT351','S119','Chuyển tiền cho bạn qua app ngân hàng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V351','SIT351','P1','suon_se','ban_chinh_thuc',NULL,'国内手机银行转账实时到账，会自动发送短信通知，转账前务必核对姓名卡号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_01','V351','阮明',1,'你好，我想在手机银行APP给同学转账。','nǐ hǎo， wǒ xiǎng zài shǒu jī yín háng APP gěi tóng xué zhuǎn zhàng。','Chào chị, em muốn chuyển tiền cho bạn học qua app ngân hàng trên điện thoại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_02','V351','客服',2,'您好，您需要输入对方银行卡号和姓名核对哦。','nín hǎo， nín xū yào shū rù duì fāng yín háng kǎ hào hé xìng míng hé duì ó。','Chào em, em cần nhập số thẻ ngân hàng và tên của người nhận để đối chiếu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_03','V351','阮明',3,'转账有限额吗，我一次转三千元可以吗？','zhuǎn zhàng yǒu xiàn é ma， wǒ yī cì zhuǎn sān qiān yuán kě yǐ ma？','Chuyển tiền có giới hạn không ạ, em chuyển một lần ba nghìn tệ được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_04','V351','客服',4,'学生一类银行卡单日转账限额五万元，完全没问题。','xué shēng yī lèi yín háng kǎ dān rì zhuǎn zhàng xiàn é wǔ wàn yuán， wán quán méi wèn tí。','Thẻ ngân hàng loại dành cho sinh viên hạn mức chuyển tiền một ngày là năm mươi nghìn tệ, hoàn toàn thoải mái.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_05','V351','阮明',5,'转账成功之后会有短信通知双方吗？','zhuǎn zhàng chéng gōng zhī hòu huì yǒu duǎn xìn tōng zhī shuāng fāng ma？','Chuyển thành công rồi thì có tin nhắn báo cho cả hai bên không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_06','V351','客服',6,'双方都会收到提醒，方便核对交易记录呢。','shuāng fāng dōu huì shōu dào tí xǐng， fāng biàn hé duì jiāo yì jì lù ne。','Cả hai bên đều nhận được thông báo, tiện cho việc đối chiếu giao dịch đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_07','V351','阮明',7,'清楚操作流程了，谢谢你的讲解吧。','qīng chǔ cāo zuò liú chéng le， xiè xiè nǐ de jiǎng jiě ba。','Em hiểu quy trình rồi, cảm ơn chị đã giải thích nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT352','S119','Nhận tiền gia đình gửi từ nước ngoài',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V352','SIT352','P1','twist','chinh_thuc',NULL,'境外跨境汇款需要银行系统清算，无法实时兑换人民币取现，留学生需携带护照办理外汇业务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_01','V352','阮明',1,'您好，我家人从境外给我汇了一笔生活费，我来办理结汇。','nín hǎo， wǒ jiā rén cóng jìng wài gěi wǒ huì le yī bǐ shēng huó fèi， wǒ lái bàn lǐ jié huì。','Chào chị, gia đình em từ nước ngoài gửi cho em một khoản sinh hoạt phí, em đến làm thủ tục kết hối ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_02','V352','柜员',2,'请出示你的护照和银行卡，我先查询外汇到账状态。','qǐng chū shì nǐ de hù zhào hé yín háng kǎ， wǒ xiān chá xún wài huì dào zhàng zhuàng tài。','Em cho chị xem hộ chiếu và thẻ ngân hàng, chị kiểm tra tình trạng tiền ngoại tệ về tài khoản trước đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_03','V352','阮明',3,'好，证件都在这里，大概昨天傍晚汇出的。','hǎo， zhèng jiàn dōu zài zhè lǐ， dà gài zuó tiān bàng wǎn huì chū de。','Dạ, giấy tờ đây ạ, hình như tiền được chuyển đi từ chiều tối hôm qua.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_04','V352','柜员',4,'抱歉，这笔汇款还未清算，今天暂时无法提取嘛。','bào qiàn， zhè bǐ huì kuǎn hái wèi qīng suàn， jīn tiān zàn shí wú fǎ tí qǔ ma。','Xin lỗi em, khoản tiền này chưa được thanh toán bù trừ xong, hôm nay tạm thời chưa rút được đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_05','V352','阮明',5,'啊？那要等到什么时候才能兑换人民币？','a？ nà yào děng dào shén me shí hòu cái néng duì huàn rén mín bì？','Ơ? Vậy phải đợi đến khi nào mới đổi được sang nhân dân tệ ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_06','V352','柜员',6,'明天上午系统完成清算，你再来柜台办理就行。','míng tiān shàng wǔ xì tǒng wán chéng qīng suàn， nǐ zài lái guì tái bàn lǐ jiù xíng。','Sáng mai hệ thống hoàn tất thanh toán bù trừ, em quay lại quầy làm là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_07','V352','阮明',7,'好，我明天一早过来，麻烦你登记一下。','hǎo， wǒ míng tiān yī zǎo guò lái， má fán nǐ dēng jì yī xià。','Dạ vâng, sáng mai em đến sớm, phiền chị ghi chú giúp em với.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT353','S119','Rút tiền tại ATM',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V353','SIT353','P1','suon_se','tuy_y',NULL,'国内ATM取款有现金上限，忘记取卡会被机器回收，需要带身份证去柜台取回。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_01','V353','阮明',1,'学长，这个ATM机怎么取款，我不太会操作啊。','xué zhǎng， zhè ge ATM jī zěn me qǔ kuǎn， wǒ bù tài huì cāo zuò a。','Anh ơi, cái máy ATM này rút tiền kiểu gì vậy, em không rành lắm.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_02','V353','学长',2,'先插银行卡，输入密码，再选择取款金额就行啦。','xiān chā yín háng kǎ， shū rù mì mǎ， zài xuǎn zé qǔ kuǎn jīn é jiù xíng la。','Cắm thẻ ngân hàng vào trước, nhập mật khẩu, rồi chọn số tiền cần rút là xong à.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_03','V353','阮明',3,'单日最多能取多少现金，会不会有限制？','dān rì zuì duō néng qǔ duō shǎo xiàn jīn， huì bú huì yǒu xiàn zhì？','Một ngày rút được tối đa bao nhiêu tiền mặt vậy, có giới hạn gì không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_04','V353','学长',4,'ATM单日限额两万，日常取生活费完全够用呢。','ATM dān rì xiàn é liǎng wàn， rì cháng qǔ shēng huó fèi wán quán gòu yòng ne。','ATM giới hạn hai chục nghìn một ngày, rút tiền sinh hoạt hàng ngày là đủ xài rồi đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_05','V353','阮明',5,'取完钱之后一定要记得拔卡对吧？','qǔ wán qián zhī hòu yí dìng yào jì de bá kǎ duì ba？','Rút tiền xong nhớ phải rút thẻ ra liền đúng không anh?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_06','V353','学长',6,'没错，超时不取卡机器会自动吞卡的。','méi cuò， chāo shí bù qǔ kǎ jī qì huì zì dòng tūn kǎ de。','Đúng rồi, để quá lâu không rút thẻ máy sẽ tự động nuốt thẻ đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_07','V353','阮明',7,'太感谢你提醒我，不然我很容易忘啦。','tài gǎn xiè nǐ tí xǐng wǒ， bù rán wǒ hěn róng yì wàng la。','Cảm ơn anh nhắc em nhiều lắm, không thì em dễ quên lắm luôn.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT354','S119','Báo mất thẻ và xin khóa thẻ khẩn cấp',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V354','SIT354','P1','suon_se','chinh_thuc',NULL,'银行卡丢失第一时间电话挂失锁卡，能保障账户资金安全，补办卡片必须线下网点办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_01','V354','阮明',1,'您好，我的银行卡遗失了，申请紧急挂失锁卡。','nín hǎo， wǒ de yín háng kǎ yí shī le， shēn qǐng jǐn jí guà shī suǒ kǎ。','Xin chào, thẻ ngân hàng của tôi bị mất, tôi muốn báo mất khẩn cấp và khóa thẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_02','V354','客服',2,'请告知您姓名、银行卡尾号以及身份证号吧。','qǐng gào zhī nín xìng míng、 yín háng kǎ wěi hào yǐ jí shēn fèn zhèng hào ba。','Xin quý khách vui lòng cho biết họ tên, bốn số cuối thẻ ngân hàng và số căn cước công dân ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_03','V354','阮明',3,'全部信息我都记好了，现在报给你核对。','quán bù xìn xī wǒ dōu jì hǎo le， xiàn zài bào gěi nǐ hé duì。','Tôi đã ghi nhớ đầy đủ thông tin rồi, bây giờ tôi đọc để anh chị kiểm tra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_04','V354','客服',4,'已经为您临时冻结卡片，资金不会被盗刷呢。','yǐ jīng wèi nín lín shí dòng jié kǎ piàn， zī jīn bú huì bèi dào shuā ne。','Chúng tôi đã tạm thời phong tỏa thẻ của quý khách, số tiền trong tài khoản sẽ không bị đánh cắp đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_05','V354','阮明',5,'那之后补办新卡需要去线下柜台办理吗？','nà zhī hòu bǔ bàn xīn kǎ xū yào qù xiàn xià guì tái bàn lǐ ma？','Vậy sau đó muốn làm lại thẻ mới thì có cần đến quầy giao dịch trực tiếp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_06','V354','客服',6,'是的，携带护照前往就近网点即可补办。','shì de， xié dài hù zhào qián wǎng jiù jìn wǎng diǎn jí kě bǔ bàn。','Vâng, quý khách chỉ cần mang theo hộ chiếu đến chi nhánh gần nhất là có thể làm lại thẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_07','V354','阮明',7,'太感谢了，还好及时打电话挂失啦。','tài gǎn xiè le， hái hǎo jí shí dǎ diàn huà guà shī la。','Cảm ơn anh chị rất nhiều, may mà tôi gọi điện báo mất kịp thời.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT355','S119','Yêu cầu in sao kê giao dịch',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V355','SIT355','P1','suon_se','ban_chinh_thuc',NULL,'留学生打印银行卡流水用于留学报备，多数银行免费办理，打印文件加盖公章才具备证明效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_01','V355','阮明',1,'你好，我需要打印近半年的银行卡交易流水。','nǐ hǎo， wǒ xū yào dǎ yìn jìn bàn nián de yín háng kǎ jiāo yì liú shuǐ。','Chào chị, tôi cần in sao kê giao dịch thẻ ngân hàng trong nửa năm gần đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_02','V355','柜员',2,'可以，出示你的银行卡和护照，我帮你调取记录哦。','kě yǐ， chū shì nǐ de yín háng kǎ hé hù zhào， wǒ bāng nǐ diào qǔ jì lù ó。','Được ạ, anh cho em xem thẻ ngân hàng và hộ chiếu, em sẽ tra cứu giúp anh nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_03','V355','阮明',3,'打印流水需要收取手续费吗？','dǎ yìn liú shuǐ xū yào shōu qǔ shǒu xù fèi ma？','In sao kê như vậy có mất phí không vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_04','V355','柜员',4,'留学生办理留学相关流水打印是免费的呢。','liú xué shēng bàn lǐ liú xué xiāng guān liú shuǐ dǎ yìn shì miǎn fèi de ne。','Du học sinh in sao kê phục vụ mục đích du học thì được miễn phí đó ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_05','V355','阮明',5,'太好了，我要交给学校作为资金证明材料。','tài hǎo le， wǒ yào jiāo gěi xué xiào zuò wéi zī jīn zhèng míng cái liào。','Vậy tốt quá, tôi cần nộp cho trường để làm chứng minh tài chính.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_06','V355','柜员',6,'我会帮你加盖银行公章，学校可以直接认可。','wǒ huì bāng nǐ jiā gài yín háng gōng zhāng， xué xiào kě yǐ zhí jiē rèn kě。','Em sẽ đóng dấu ngân hàng lên giúp anh, để trường có thể công nhận trực tiếp luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_07','V355','阮明',7,'辛苦你了，等下我取完流水就离开。','xīn kǔ nǐ le， děng xià wǒ qǔ wán liú shuǐ jiù lí kāi。','Cảm ơn chị đã vất vả, lấy sao kê xong tôi sẽ về ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT356','S119','Đổi mã PIN thẻ ngân hàng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V356','SIT356','P1','twist','tuy_y',NULL,'银行取款密码固定六位数，修改时两次输入必须完全相同，不一致则操作失败。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_01','V356','阮明',1,'你好，我想在自助终端修改银行卡取款密码。','nǐ hǎo， wǒ xiǎng zài zì zhù zhōng duān xiū gǎi yín háng kǎ qǔ kuǎn mì mǎ。','Chào bạn, mình muốn đổi mật khẩu rút tiền của thẻ ngân hàng ở máy tự phục vụ này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_02','V356','引导员',2,'先插卡输入旧密码，再设置新的六位数字密码。','xiān chā kǎ shū rù jiù mì mǎ， zài shè zhì xīn de liù wèi shù zì mì mǎ。','Bạn cắm thẻ vào, nhập mật khẩu cũ trước, rồi đặt mật khẩu mới sáu chữ số nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_03','V356','阮明',3,'我刚刚输入一遍，提示两次密码不一致嘛。','wǒ gāng gāng shū rù yī biàn， tí shì liǎng cì mì mǎ bù yī zhì ma。','Mình vừa nhập rồi mà, máy báo hai lần mật khẩu không khớp nè.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_04','V356','阮明',4,'我没看清屏幕，两次输的数字不一样。','wǒ méi kàn qīng píng mù， liǎng cì shū de shù zì bù yí yàng。','Mình nhìn không rõ màn hình, nên hai lần nhập số khác nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_05','V356','引导员',5,'没关系，重新操作一次，仔细核对数字就行。','méi guān xì， chóng xīn cāo zuò yī cì， zǐ xì hé duì shù zì jiù xíng。','Không sao đâu, làm lại một lần nữa, chú ý nhìn kỹ số là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_06','V356','阮明',6,'好，我慢慢来，这次一定留意屏幕提示。','hǎo， wǒ màn màn lái， zhè cì yí dìng liú yì píng mù tí shì。','Ừ, để mình từ từ, lần này chắc chắn sẽ để ý kỹ thông báo trên màn hình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_07','V356','阮明',7,'终于修改成功了，谢谢你在旁边指导我啦。','zhōng yú xiū gǎi chéng gōng le， xiè xiè nǐ zài páng biān zhǐ dǎo wǒ la。','Cuối cùng cũng đổi thành công rồi, cảm ơn bạn đã đứng bên hướng dẫn mình nha.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT357','S119','Hỏi phí chuyển tiền quốc tế',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V357','SIT357','P1','suon_se','chinh_thuc',NULL,'国际跨境转账手续费固定收取，到账速度受国内外节假日、银行清算时间影响。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_01','V357','阮明',1,'您好，如果我往越南的账户转账，手续费怎么收取？','nín hǎo， rú guǒ wǒ wǎng yuè nán de zhàng hù zhuǎn zhàng， shǒu xù fèi zěn me shōu qǔ？','Xin chào, nếu tôi chuyển tiền đến tài khoản ở Việt Nam thì phí giao dịch được tính như thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_02','V357','柜员',2,'手续费分为固定工本费和跨境电讯费两部分哦。','shǒu xù fèi fēn wéi gù dìng gōng běn fèi hé kuà jìng diàn xùn fèi liǎng bù fèn ó。','Phí giao dịch gồm hai phần: phí xử lý cố định và phí điện báo chuyển tiền quốc tế ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_03','V357','阮明',3,'转账金额不同，手续费价格会变化吗？','zhuǎn zhàng jīn é bù tóng， shǒu xù fèi jià gé huì biàn huà ma？','Số tiền chuyển khác nhau thì phí có thay đổi theo không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_04','V357','柜员',4,'手续费统一标准，不会随转账金额增减呢。','shǒu xù fèi tǒng yī biāo zhǔn， bú huì suí zhuǎn zhàng jīn é zēng jiǎn ne。','Phí được áp dụng theo mức cố định, không tăng giảm theo số tiền chuyển đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_05','V357','阮明',5,'那多久能到对方的海外银行卡账户？','nà duō jiǔ néng dào duì fāng de hǎi wài yín háng kǎ zhàng hù？','Vậy mất bao lâu thì tiền sẽ đến tài khoản ngân hàng ở nước ngoài ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_06','V357','柜员',6,'最快两个工作日，节假日会顺延清算时间。','zuì kuài liǎng gè gōng zuò rì， jié jià rì huì shùn yán qīng suàn shí jiān。','Nhanh nhất là hai ngày làm việc, nếu gặp ngày lễ thì thời gian thanh toán sẽ bị lùi lại ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_07','V357','阮明',7,'我全部了解清楚了，感谢你的细致讲解。','wǒ quán bù liǎo jiě qīng chǔ le， gǎn xiè nǐ de xì zhì jiǎng jiě。','Tôi đã hiểu rõ hết rồi, cảm ơn anh chị đã giải thích tận tình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT358','S119','Khiếu nại giao dịch bị trừ tiền nhưng không nhận được hàng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V358','SIT358','P1','twist','ban_chinh_thuc',NULL,'国内电商平台漏发、丢件，顾客可自主选择补发货物或全额退款，平台客服全程协调处理；商家责任退款自动审核，到账速度更快。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_01','V358','阮明',1,'你好，我要反馈一笔线上订单问题，支付扣款成功，至今没有收到包裹。','nǐ hǎo， wǒ yào fǎn kuì yī bǐ xiàn shàng dìng dān wèn tí， zhī fù kòu kuǎn chéng gōng， zhì jīn méi yǒu shōu dào bāo guǒ。','Chào bạn, tôi muốn phản ánh một đơn hàng online, tiền đã bị trừ thành công nhưng đến giờ vẫn chưa nhận được hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_02','V358','客服',2,'您好，麻烦先提供一下完整订单编号，我调取后台物流配送记录哈。','nín hǎo， má fán xiān tí gōng yī xià wán zhěng dìng dān biān hào， wǒ diào qǔ hòu tái wù liú pèi sòng jì lù hā。','Chào anh, phiền anh cung cấp mã đơn hàng đầy đủ trước để em tra cứu thông tin vận chuyển trên hệ thống nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_03','V358','阮明',3,'订单编号我复制在这里发给你，物流页面从下单当天一直显示待揽收状态呢。','dìng dān biān hào wǒ fù zhì zài zhè lǐ fā gěi nǐ， wù liú yè miàn cóng xià dān dàng tiān yì zhí xiǎn shì dài lǎn shōu zhuàng tài ne。','Mã đơn hàng tôi copy gửi cho bạn đây, trang theo dõi vận chuyển từ lúc đặt hàng đến giờ vẫn báo trạng thái chờ lấy hàng.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_04','V358','客服',4,'我调取仓库发货台账核对，查到是仓库工作人员漏打包商品，实在非常抱歉。','wǒ diào qǔ cāng kù fā huò tái zhàng hé duì， chá dào shì cāng kù gōng zuò rén yuán lòu dǎ bāo shāng pǐn， shí zài fēi cháng bào qiàn。','Em đã kiểm tra sổ xuất kho, phát hiện nhân viên kho đã sót không đóng gói sản phẩm, thật sự rất xin lỗi anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_05','V358','阮明',5,'我下单已经七天，一直等待收货，耽误了我的使用计划，心里挺着急的。','wǒ xià dān yǐ jīng qī tiān， yì zhí děng dài shōu huò， dān wù le wǒ de shǐ yòng jì huà， xīn lǐ tǐng zháo jí de。','Tôi đặt hàng đã bảy ngày rồi, cứ chờ mãi mà không nhận được, làm lỡ kế hoạch sử dụng của tôi, tôi thấy khá sốt ruột.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_06','V358','客服',6,'针对漏发问题平台提供两种解决方案，您可以自由选择，没有强制要求。','zhēn duì lòu fā wèn tí píng tái tí gōng liǎng zhǒng jiě jué fāng àn， nín kě yǐ zì yóu xuǎn zé， méi yǒu qiáng zhì yāo qiú。','Đối với vấn đề sót hàng này, sàn có hai phương án giải quyết, anh có thể tự chọn, không bắt buộc gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_07','V358','阮明',7,'那现在第一种方案补发商品、第二种全额退款，两种分别需要等待多久？','nà xiàn zài dì yī zhǒng fāng àn bǔ fā shāng pǐn、 dì èr zhǒng quán é tuì kuǎn， liǎng zhǒng fēn bié xū yào děng dài duō jiǔ？','Vậy phương án một là gửi lại hàng, phương án hai là hoàn tiền toàn bộ, mỗi cái cần chờ bao lâu vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_08','V358','客服',8,'选择补发需要重新排单发货，仓库备货需要再等三天；退款申请提交当日原路返还资金。','xuǎn zé bǔ fā xū yào chóng xīn pái dān fā huò， cāng kù bèi huò xū yào zài děng sān tiān； tuì kuǎn shēn qǐng tí jiāo dāng rì yuán lù fǎn huán zī jīn。','Nếu chọn gửi lại hàng thì phải xếp đơn giao lại, kho cần thêm ba ngày để chuẩn bị hàng; còn nếu hoàn tiền thì ngay trong ngày nộp yêu cầu tiền sẽ được hoàn về theo đường thanh toán cũ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_09','V358','阮明',9,'我急需这件商品使用，不想再额外等待三天补发货品。','wǒ jí xū zhè jiàn shāng pǐn shǐ yòng， bù xiǎng zài é wài děng dài sān tiān bǔ fā huò pǐn。','Tôi đang cần gấp món hàng này để dùng, không muốn đợi thêm ba ngày để nhận hàng gửi lại nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_10','V358','客服',10,'我明白您的需求，那我直接为您提交全额退款售后申请。','wǒ míng bái nín de xū qiú， nà wǒ zhí jiē wèi nín tí jiāo quán é tuì kuǎn shòu hòu shēn qǐng。','Em hiểu nhu cầu của anh rồi, vậy em sẽ nộp luôn yêu cầu hoàn tiền toàn bộ cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_11','V358','阮明',11,'退款审核会不会需要人工排队，延迟好几天到账？','tuì kuǎn shěn hé huì bú huì xū yào rén gōng pái duì， yán chí hǎo jǐ tiān dào zhàng？','Việc duyệt hoàn tiền có cần xếp hàng xử lý thủ công không, có bị chậm mấy ngày mới về tài khoản không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_12','V358','客服',12,'漏发属于商家全责，退款自动审核，几分钟内就能完成资金返还。','lòu fā shǔ yú shāng jiā quán zé， tuì kuǎn zì dòng shěn hé， jǐ fēn zhōng nèi jiù néng wán chéng zī jīn fǎn huán。','Trường hợp sót hàng là lỗi hoàn toàn của người bán, nên hoàn tiền sẽ được duyệt tự động, chỉ vài phút là tiền về lại tài khoản thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_13','V358','阮明',13,'那就直接办理全额退款吧，我不想继续等待补发货物了。','nà jiù zhí jiē bàn lǐ quán é tuì kuǎn ba， wǒ bù xiǎng jì xù děng dài bǔ fā huò wù le。','Vậy thì làm thủ tục hoàn tiền toàn bộ luôn đi, tôi không muốn chờ gửi lại hàng nữa.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_14','V358','客服',14,'申请已提交，您留意支付软件的到账通知即可。','shēn qǐng yǐ tí jiāo， nín liú yì zhī fù ruǎn jiàn de dào zhàng tōng zhī jí kě。','Yêu cầu đã được gửi rồi ạ, anh chỉ cần chú ý thông báo nhận tiền trên ứng dụng thanh toán là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_15','V358','阮明',15,'好，感谢快速处理我的售后投诉。','hǎo， gǎn xiè kuài sù chǔ lǐ wǒ de shòu hòu tóu sù。','Được, cảm ơn bạn đã xử lý nhanh khiếu nại của tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT359','S120','Hỏi tuyến xe buýt đến trung tâm thành phố',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V359','SIT359','P1','suon_se','tuy_y',NULL,'国内城市公交支持手机二维码扫码乘车，无需单独购买公交卡，出行更方便。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_01','V359','阮明',1,'大叔您好，我想去市中心步行街，该坐哪一路公交啊？','dà shū nín hǎo， wǒ xiǎng qù shì zhōng xīn bù xíng jiē， gāi zuò nǎ yī lù gōng jiāo a？','Chào chú, cháu muốn đi phố đi bộ trung tâm thành phố thì bắt xe buýt tuyến nào ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_02','V359','保安大叔',2,'出门右转站台坐12路，终点站就是市中心啦。','chū mén yòu zhuǎn zhàn tái zuò 12 lù， zhōng diǎn zhàn jiù shì shì zhōng xīn la。','Ra khỏi cửa rẽ phải là tới trạm, cháu lên xe tuyến 12, trạm cuối chính là trung tâm thành phố đó.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_03','V359','阮明',3,'一趟车程大概要多久，会不会经常堵车呢？','yī tàng chē chéng dà gài yào duō jiǔ， huì bú huì jīng cháng dǔ chē ne？','Đi một chuyến mất khoảng bao lâu vậy chú, có hay bị kẹt xe không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_04','V359','保安大叔',4,'不堵车四十分钟，下班高峰期会慢一点。','bù dǔ chē sì shí fēn zhōng， xià bān gāo fēng qī huì màn yì diǎn。','Không kẹt xe thì bốn mươi phút, giờ tan tầm thì sẽ chậm hơn một chút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_05','V359','阮明',5,'公交支持手机扫码乘车，不用办实体卡对吧？','gōng jiāo zhī chí shǒu jī sǎo mǎ chéng chē， bù yòng bàn shí tǐ kǎ duì ba？','Xe buýt có hỗ trợ quét mã QR trên điện thoại để lên xe, không cần làm thẻ cứng đúng không chú?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_06','V359','保安大叔',6,'没错，调出乘车码直接扫码就能上车。','méi cuò， diào chū chéng chē mǎ zhí jiē sǎo mǎ jiù néng shàng chē。','Đúng rồi, cháu mở mã lên xe ra rồi quét là lên xe được luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_07','V359','阮明',7,'太感谢大叔指路，我现在就去站台等车吧。','tài gǎn xiè dà shū zhǐ lù， wǒ xiàn zài jiù qù zhàn tái děng chē ba。','Cháu cảm ơn chú chỉ đường nhiều lắm, giờ cháu ra trạm đợi xe luôn đây.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT360','S121','Nạp tiền vào thẻ tàu điện',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V360','SIT360','P1','twist','tuy_y',NULL,'地铁自助充值机偶尔出现系统延迟扣款不到账，等待片刻或联系站内工作人员即可解决。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_01','V360','阮明',1,'同学，这个自助机怎么给地铁交通卡充值啊？','tóng xué， zhè ge zì zhù jī zěn me gěi dì tiě jiāo tōng kǎ chōng zhí a？','Bạn ơi, cái máy tự động này nạp tiền cho thẻ tàu điện kiểu gì vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_02','V360','志愿者',2,'先把卡片放在感应区，再选择充值金额扫码付款。','xiān bǎ kǎ piàn fàng zài gǎn yìng qū， zài xuǎn zé chōng zhí jīn é sǎo mǎ fù kuǎn。','Bạn đặt thẻ vào khu vực cảm ứng trước, rồi chọn số tiền cần nạp và quét mã thanh toán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_03','V360','阮明',3,'我扫码支付之后，机器提示充值失败嘛。','wǒ sǎo mǎ zhī fù zhī hòu， jī qì tí shì chōng zhí shī bài ma。','Mình quét mã thanh toán xong rồi mà máy lại báo nạp tiền thất bại nè.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_04','V360','阮明',4,'手机扣款了，但是卡里余额没有增加。','shǒu jī kòu kuǎn le， dàn shì kǎ lǐ yú é méi yǒu zēng jiā。','Điện thoại đã bị trừ tiền rồi, nhưng số dư trong thẻ lại không tăng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_05','V360','志愿者',5,'别着急，系统延迟，五分钟后再查询余额就行。','bié zháo jí， xì tǒng yán chí， wǔ fēn zhōng hòu zài chá xún yú é jiù xíng。','Đừng lo, hệ thống bị trễ thôi, đợi năm phút rồi kiểm tra lại số dư là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_06','V360','阮明',6,'原来是系统卡顿，我等一会儿再看余额。','yuán lái shì xì tǒng kǎ dùn， wǒ děng yī huì er zài kàn yú é。','Thì ra là hệ thống bị lag, để mình đợi một lát rồi xem lại số dư.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_07','V360','阮明',7,'还好有你帮忙讲解，不然我都不知道怎么办啦。','hái hǎo yǒu nǐ bāng máng jiǎng jiě， bù rán wǒ dōu bù zhī dào zěn me bàn la。','May mà có bạn giúp giải thích, không thì mình chẳng biết phải làm sao luôn.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT361','S122','Mở khóa và thuê xe đạp công cộng qua app',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V361','SIT361','P1','twist','tuy_y',NULL,'国内共享单车依靠手机App扫码、蓝牙联动解锁，故障车辆可免费更换，不会扣费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_01','V361','阮明',1,'同学，我扫码共享单车怎么一直开锁失败啊？','tóng xué， wǒ sǎo mǎ gòng xiǎng dān chē zěn me yì zhí kāi suǒ shī bài a？','Bạn ơi, sao mình quét mã xe đạp chung mà mở khóa hoài không được vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_02','V361','小杨',2,'你看看手机蓝牙开了吗，骑车必须打开蓝牙呢。','nǐ kàn kàn shǒu jī lán yá kāi le ma， qí chē bì xū dǎ kāi lán yá ne。','Bạn xem thử điện thoại bật Bluetooth chưa, đi xe là phải bật Bluetooth đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_03','V361','阮明',3,'蓝牙是打开的，页面一直显示车辆故障。','lán yá shì dǎ kāi de， yè miàn yì zhí xiǎn shì chē liàng gù zhàng。','Bluetooth bật rồi mà, trên màn hình cứ báo xe bị hỏng hoài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_04','V361','小杨',4,'那这辆车出问题了，直接点换车按钮就行啦。','nà zhè liàng chē chū wèn tí le， zhí jiē diǎn huàn chē àn niǔ jiù xíng la。','Vậy là xe đó bị lỗi rồi, cứ bấm nút đổi xe khác là được.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_05','V361','阮明',5,'原来是这样，我还以为是我的账号有问题。','yuán lái shì zhè yàng， wǒ hái yǐ wéi shì wǒ de zhàng hào yǒu wèn tí。','Thì ra là vậy, mình còn tưởng tài khoản của mình bị sao.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_06','V361','小杨',6,'路边很多备用单车，换一辆很快就能解锁。','lù biān hěn duō bèi yòng dān chē， huàn yī liàng hěn kuài jiù néng jiě suǒ。','Bên đường có nhiều xe dự phòng lắm, đổi xe khác là mở khóa được ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_07','V361','阮明',7,'太谢谢你提醒我，不然我要在这里耗好久。','tài xiè xiè nǐ tí xǐng wǒ， bù rán wǒ yào zài zhè lǐ hào hǎo jiǔ。','Cảm ơn bạn nhắc mình quá, không thì chắc mình đứng đây lâu lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT362','S123','Thuê xe máy điện ngắn ngày',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V362','SIT362','P1','suon_se','ban_chinh_thuc',NULL,'国内电动车租赁门店大多需要押证件，归还车辆无损坏后立即返还证件押金。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_01','V362','阮明',1,'老板你好，我想租一辆电动车，只用半天可以吗？','lǎo bǎn nǐ hǎo， wǒ xiǎng zū yī liàng diàn dòng chē， zhǐ yòng bàn tiān kě yǐ ma？','Chào anh, tôi muốn thuê một chiếc xe điện, chỉ dùng nửa ngày thôi có được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_02','V362','老板',2,'没问题，半天三十块，需要押你的护照登记哦。','méi wèn tí， bàn tiān sān shí kuài， xū yào yā nǐ de hù zhào dēng jì ó。','Được chứ, nửa ngày ba mươi tệ, cần thế chấp hộ chiếu để đăng ký nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_03','V362','阮明',3,'骑车去城郊景点，电量来回足够吗？','qí chē qù chéng jiāo jǐng diǎn， diàn liàng lái huí zú gòu ma？','Đi xe ra khu du lịch ngoại ô, pin đi về có đủ không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_04','V362','老板',4,'满电续航五十公里，短途出行完全够用的。','mǎn diàn xù háng wǔ shí gōng lǐ， duǎn tú chū xíng wán quán gòu yòng de。','Sạc đầy đi được năm mươi cây số, đi loanh quanh gần thì thoải mái đủ dùng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_05','V362','阮明',5,'路上万一没电，店里有应急充电设备吧？','lù shàng wàn yī méi diàn， diàn lǐ yǒu yìng jí chōng diàn shè bèi ba？','Lỡ giữa đường hết pin thì cửa hàng có thiết bị sạc khẩn cấp không anh?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_06','V362','老板',6,'店里有便携充电器，你可以随身带着备用。','diàn lǐ yǒu biàn xié chōng diàn qì， nǐ kě yǐ suí shēn dài zhe bèi yòng。','Cửa hàng có bộ sạc di động, chị có thể mang theo bên mình phòng khi cần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_07','V362','阮明',7,'好，那我现在登记租车，麻烦你啦。','hǎo， nà wǒ xiàn zài dēng jì zū chē， má fán nǐ la。','Được rồi, vậy giờ tôi đăng ký thuê xe luôn, làm phiền anh nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT363','S124','Mua vé tàu cao tốc về quê vào kỳ nghỉ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V363','SIT363','P1','twist','ban_chinh_thuc',NULL,'外籍留学生使用护照购买高铁票，部分自助设备无法识别，必须前往人工窗口办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_01','V363','阮明',1,'你好，我想用自助机买一张周末去邻市的高铁票。','nǐ hǎo， wǒ xiǎng yòng zì zhù jī mǎi yī zhāng zhōu mò qù lín shì de gāo tiě piào。','Chào chị, tôi muốn dùng máy tự động mua vé tàu cao tốc cuối tuần đi thành phố lân cận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_02','V363','引导员',2,'先把护照放在读卡区，再输入目的地站点就行。','xiān bǎ hù zhào fàng zài dú kǎ qū， zài shū rù mù dì dì zhàn diǎn jiù xíng。','Anh đặt hộ chiếu vào khu vực đọc thẻ trước, rồi nhập ga đến là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_03','V363','阮明',3,'我选好车次，系统提示外籍证件无法线上核验嘛。','wǒ xuǎn hǎo chē cì， xì tǒng tí shì wài jí zhèng jiàn wú fǎ xiàn shàng hé yàn ma。','Tôi chọn xong chuyến tàu rồi, mà hệ thống báo giấy tờ người nước ngoài không xác thực online được nè.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_04','V363','引导员',4,'这种情况要去人工窗口，工作人员手动录入信息。','zhè zhǒng qíng kuàng yào qù rén gōng chuāng kǒu， gōng zuò rén yuán shǒu dòng lù rù xìn xī。','Trường hợp này anh phải ra quầy có nhân viên, họ sẽ nhập thông tin thủ công cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_05','V363','阮明',5,'人工窗口排队人多吗，大概要等多久呢？','rén gōng chuāng kǒu pái duì rén duō ma， dà gài yào děng duō jiǔ ne？','Quầy nhân viên có đông người xếp hàng không, chắc phải đợi bao lâu vậy chị?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_06','V363','引导员',6,'现在人不多，十分钟左右就能完成购票。','xiàn zài rén bù duō， shí fēn zhōng zuǒ yòu jiù néng wán chéng gòu piào。','Giờ không đông đâu, khoảng mười phút là mua vé xong thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_07','V363','阮明',7,'好，我马上过去人工窗口办理，感谢指引。','hǎo， wǒ mǎ shàng guò qù rén gōng chuāng kǒu bàn lǐ， gǎn xiè zhǐ yǐn。','Được rồi, tôi ra quầy nhân viên ngay, cảm ơn chị đã chỉ dẫn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT364','S124','Đổi vé tàu cao tốc vì thay đổi lịch trình',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V364','SIT364','P1','suon_se','ban_chinh_thuc',NULL,'高铁车票发车前可免费改签一次，仅变更乘车时间，目的地不变无需额外付费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_01','V364','阮明',1,'您好，我买了明天上午的高铁票，想改签成下午班次。','nín hǎo， wǒ mǎi le míng tiān shàng wǔ de gāo tiě piào， xiǎng gǎi qiān chéng xià wǔ bān cì。','Chào chị, tôi mua vé tàu cao tốc sáng mai rồi, giờ muốn đổi sang chuyến buổi chiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_02','V364','售票员',2,'出示购票用的护照，我帮你查询余票情况哈。','chū shì gòu piào yòng de hù zhào， wǒ bāng nǐ chá xún yú piào qíng kuàng hā。','Anh đưa hộ chiếu lúc mua vé ra đây, để tôi kiểm tra vé còn trống giúp anh nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_03','V364','阮明',3,'改签需要额外收取手续费吗？','gǎi qiān xū yào é wài shōu qǔ shǒu xù fèi ma？','Đổi vé như vậy có bị tính thêm phí gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_04','V364','售票员',4,'发车前免费改签一次，第二次改签才会收费呢。','fā chē qián miǎn fèi gǎi qiān yī cì， dì èr cì gǎi qiān cái huì shōu fèi ne。','Trước giờ tàu chạy thì được đổi vé miễn phí một lần, đổi lần thứ hai mới bị tính phí nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_05','V364','阮明',5,'下午三点那趟还有空余座位对吧？','xià wǔ sān diǎn nà tàng hái yǒu kòng yú zuò wèi duì ba？','Chuyến ba giờ chiều còn chỗ trống đúng không chị?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_06','V364','售票员',6,'还有二等座，我直接帮你更改车次信息。','hái yǒu èr děng zuò， wǒ zhí jiē bāng nǐ gēng gǎi chē cì xìn xī。','Còn ghế hạng hai, để tôi đổi luôn thông tin chuyến tàu cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_07','V364','阮明',7,'辛苦你了，行程临时变动实在不好意思。','xīn kǔ nǐ le， xíng chéng lín shí biàn dòng shí zài bù hǎo yì sī。','Cảm ơn chị nhiều, lịch trình đổi đột xuất thế này thật ngại quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT365','S125','Đặt taxi đi khám bệnh gấp',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V365','SIT365','P1','suon_se','ban_chinh_thuc',NULL,'网约车支持目的地精准定位，紧急就医可备注需求，司机会优先规划快速路线。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_01','V365','阮明',1,'师傅麻烦快一点，我身体不舒服要赶去医院啊。','shī fù má fán kuài yì diǎn， wǒ shēn tǐ bù shū fú yào gǎn qù yī yuàn a。','Anh tài xế ơi, làm ơn chạy nhanh chút giúp tôi, tôi khó chịu trong người phải gấp đến bệnh viện.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_02','V365','司机',2,'放心，我避开堵车路段，尽量缩短路上时间。','fàng xīn， wǒ bì kāi dǔ chē lù duàn， jǐn liàng suō duǎn lù shàng shí jiān。','Yên tâm đi, tôi sẽ tránh mấy đoạn kẹt xe, cố gắng rút ngắn thời gian trên đường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_03','V365','阮明',3,'到医院正门下车，不用停地下车库可以吧？','dào yī yuàn zhèng mén xià chē， bù yòng tíng dì xià chē kù kě yǐ ba？','Cho tôi xuống ngay cổng chính bệnh viện được không, không cần đỗ ở bãi xe ngầm đâu.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_04','V365','司机',4,'没问题，正门临时上下客区域可以短暂停靠。','méi wèn tí， zhèng mén lín shí shàng xià kè qū yù kě yǐ duǎn zàn tíng kào。','Không vấn đề gì, khu đón trả khách tạm thời ở cổng chính có thể dừng lại một chút được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_05','V365','阮明',5,'我头晕得厉害，麻烦开车平稳一点呢。','wǒ tóu yūn dé lì hài， má fán kāi chē píng wěn yì diǎn ne。','Tôi chóng mặt dữ lắm, làm ơn chạy êm êm chút giúp tôi nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_06','V365','司机',6,'我放慢车速，有不舒服你随时跟我说。','wǒ fàng màn chē sù， yǒu bù shū fú nǐ suí shí gēn wǒ shuō。','Tôi sẽ chạy chậm lại, nếu thấy khó chịu thì cứ nói với tôi ngay nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_07','V365','阮明',7,'太感谢师傅体谅我，到地方我立刻付款。','tài gǎn xiè shī fù tǐ liàng wǒ， dào dì fāng wǒ lì kè fù kuǎn。','Cảm ơn anh tài xế đã thông cảm cho tôi nhiều, tới nơi tôi thanh toán liền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT366','S120','Hỏi giờ chuyến xe buýt cuối cùng trong ngày',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V366','SIT366','P1','twist','tuy_y',NULL,'公交末班时间会根据工作日、节假日临时调整，站台工作人员可实时查询当日运营时刻。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_01','V366','阮明',1,'您好，请问18路公交今晚末班车几点发车呀？','nín hǎo， qǐng wèn 18 lù gōng jiāo jīn wǎn mò bān chē jǐ diǎn fā chē ya？','Chào chị, cho tôi hỏi tối nay chuyến xe buýt tuyến 18 cuối cùng mấy giờ chạy vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_02','V366','工作人员',2,'平常九点半，今天线路临时调整，九点就收班了嘛。','píng cháng jiǔ diǎn bàn， jīn tiān xiàn lù lín shí diào zhěng， jiǔ diǎn jiù shōu bān le ma。','Bình thường là chín giờ rưỡi, nhưng hôm nay tuyến điều chỉnh tạm thời nên chín giờ đã hết chuyến rồi đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_03','V366','阮明',3,'这么早？那错过这趟车还有别的换乘路线吗？','zhè me zǎo？ nà cuò guò zhè tàng chē hái yǒu bié de huàn chéng lù xiàn ma？','Sớm vậy sao? Vậy lỡ chuyến này thì còn tuyến nào chuyển tiếp được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_04','V366','工作人员',4,'可以转地铁，地铁末班车十一点才停运。','kě yǐ zhuǎn dì tiě， dì tiě mò bān chē shí yì diǎn cái tíng yùn。','Có thể chuyển sang tàu điện ngầm, chuyến cuối của tàu điện ngầm mười một giờ mới ngừng chạy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_05','V366','阮明',5,'步行到地铁站大概需要几分钟呢？','bù xíng dào dì tiě zhàn dà gài xū yào jǐ fēn zhōng ne？','Đi bộ tới ga tàu điện ngầm mất khoảng mấy phút vậy chị?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_06','V366','工作人员',6,'七八分钟，顺着人行道直走就能看见入口。','qī bā fēn zhōng， shùn zhe rén xíng dào zhí zǒu jiù néng kàn jiàn rù kǒu。','Khoảng bảy tám phút thôi, cứ đi thẳng theo vỉa hè là thấy lối vào ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_07','V366','阮明',7,'好，那我提前出发去坐地铁，多谢告知。','hǎo， nà wǒ tí qián chū fā qù zuò dì tiě， duō xiè gào zhī。','Dạ được, vậy tôi đi sớm để kịp bắt tàu điện ngầm, cảm ơn chị đã cho biết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT367','S121','Hỏi lối ra gần nhất tới địa điểm cần đến',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V367','SIT367','P1','suon_se','tuy_y',NULL,'大型商场划分专门网约车上下客出口，普通主干道禁止车辆临时停靠，避免拥堵。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_01','V367','阮明',1,'师傅，我想打车，最近的商场出口往哪边走呢？','shī fù， wǒ xiǎng dǎ chē， zuì jìn de shāng chǎng chū kǒu wǎng nǎ biān zǒu ne？','Anh ơi, tôi muốn bắt taxi, lối ra gần nhất của trung tâm thương mại đi hướng nào vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_02','V367','安保人员',2,'直走到中庭右转，一号门就是打车专用出口哦。','zhí zǒu dào zhōng tíng yòu zhuǎn， yī hào mén jiù shì dǎ chē zhuān yòng chū kǒu ó。','Đi thẳng tới sảnh giữa rồi rẽ phải, cửa số 1 chính là lối ra dành riêng cho taxi đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_03','V367','阮明',3,'一号门外面有专门的等候区域吧？','yī hào mén wài miàn yǒu zhuān mén de děng hòu qū yù ba？','Bên ngoài cửa số 1 có khu vực chờ riêng đúng không anh?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_04','V367','安保人员',4,'有的，路边不能随便停车，只能在指定区域等车。','yǒu de， lù biān bù néng suí biàn tíng chē， zhǐ néng zài zhǐ dìng qū yù děng chē。','Đúng vậy, bên đường không được đỗ xe tùy tiện, chỉ có thể chờ xe ở khu vực quy định thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_05','V367','阮明',5,'我拎了不少东西，这条路线没有台阶对吗？','wǒ līn le bù shǎo dōng xī， zhè tiáo lù xiàn méi yǒu tái jiē duì ma？','Tôi xách khá nhiều đồ, lối đi này không có bậc thang đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_06','V367','安保人员',6,'全程平坦通道，推行李箱、拎重物都方便。','quán chéng píng tǎn tōng dào， tuī xíng lǐ xiāng、 līn zhòng wù dōu fāng biàn。','Cả đoạn đường đều bằng phẳng, kéo vali hay xách đồ nặng đều thuận tiện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_07','V367','阮明',7,'清楚了，麻烦你指路啦。','qīng chǔ le， má fán nǐ zhǐ lù la。','Rõ rồi ạ, làm phiền anh chỉ đường nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT368','S123','Trả xe thuê trễ giờ, hỏi phụ phí',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V368','SIT368','P1','twist','ban_chinh_thuc',NULL,'共享电单车设置固定免费时长，超时产生溢价费用，平台优惠券一般仅抵扣基础租赁费用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_01','V368','阮明',1,'你好，我租的共享电车超时半小时，要补多少钱？','nǐ hǎo， wǒ zū de gòng xiǎng diàn chē chāo shí bàn xiǎo shí， yào bǔ duō shǎo qián？','Chào anh, tôi thuê xe điện chia sẻ mà trễ giờ nửa tiếng, phải trả thêm bao nhiêu vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_02','V368','运维员',2,'基础时长两小时，超出后每半小时加收五元哈。','jī chǔ shí cháng liǎng xiǎo shí， chāo chū hòu měi bàn xiǎo shí jiā shōu wǔ yuán hā。','Thời lượng cơ bản là hai tiếng, quá giờ thì cứ mỗi nửa tiếng tính thêm năm tệ nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_03','V368','阮明',3,'页面提示有超时罚款，不能直接抵扣优惠券嘛？','yè miàn tí shì yǒu chāo shí fá kuǎn， bù néng zhí jiē dǐ kòu yōu huì quàn ma？','Màn hình báo có phí phạt trễ giờ, không thể dùng phiếu giảm giá để trừ trực tiếp được à?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_04','V368','运维员',4,'超时产生的额外费用不支持优惠券抵扣的。','chāo shí chǎn shēng de é wài fèi yòng bù zhī chí yōu huì quàn dǐ kòu de。','Phần phí phát sinh do trễ giờ thì không áp dụng phiếu giảm giá được đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_05','V368','阮明',5,'原来是这样，那我直接微信扫码支付就行？','yuán lái shì zhè yàng， nà wǒ zhí jiē wēi xìn sǎo mǎ zhī fù jiù xíng？','Thì ra là vậy, vậy tôi quét mã WeChat thanh toán trực tiếp là được phải không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_06','V368','运维员',6,'对，站点二维码扫码就能结清所有费用。','duì， zhàn diǎn èr wéi mǎ sǎo mǎ jiù néng jié qīng suǒ yǒu fèi yòng。','Đúng rồi, quét mã QR tại trạm là thanh toán hết mọi khoản phí luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_07','V368','阮明',7,'好，我马上付款，下次一定看好还车时限。','hǎo， wǒ mǎ shàng fù kuǎn， xià cì yí dìng kàn hǎo hái chē shí xiàn。','Được rồi, tôi thanh toán ngay đây, lần sau nhất định phải để ý giờ trả xe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT369','S126','Báo mất hộ chiếu với cảnh sát',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V369','SIT369','P1','suon_se','chinh_thuc',NULL,'外籍人士丢失护照必须先到派出所开具遗失报案回执，再前往出入境大厅办理临时通行证明，后续可凭回执到本国驻华大使馆补办正式护照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_01','V369','阮明',1,'警官您好，我有紧急情况，今天出门逛街把本人护照弄丢了，前来派出所报案。','jǐng guān nín hǎo， wǒ yǒu jǐn jí qíng kuàng， jīn tiān chū mén guàng jiē bǎ běn rén hù zhào nòng diū le， qián lái pài chū suǒ bào àn。','Chào cảnh sát ạ, tôi có việc gấp, hôm nay đi dạo phố bị mất hộ chiếu của mình, nên đến đồn công an để trình báo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_02','V369','民警',2,'你先平复一下情绪，我们一步步核对信息，先告诉我你的基础个人信息。','nǐ xiān píng fù yī xià qíng xù， wǒ men yí bù bù hé duì xìn xī， xiān gào sù wǒ nǐ de jī chǔ gè rén xìn xī。','Bạn bình tĩnh lại một chút nhé, chúng ta sẽ đối chiếu thông tin từng bước một, trước tiên hãy cho tôi biết thông tin cá nhân cơ bản của bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_03','V369','阮明',3,'我叫阮明，二十二岁越南留学生，在本市高校就读汉语言专业。','wǒ jiào ruǎn míng， èr shí èr suì yuè nán liú xué shēng， zài běn shì gāo xiào jiù dú hàn yǔ yán zhuān yè。','Tôi tên là Nguyễn Minh, 22 tuổi, du học sinh Việt Nam, đang theo học ngành tiếng Trung tại một trường đại học ở thành phố này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_04','V369','民警',4,'接下来详细描述今天完整出行路线，从出门到发现遗失护照的全过程。','jiē xià lái xiáng xì miáo shù jīn tiān wán zhěng chū xíng lù xiàn， cóng chū mén dào fā xiàn yí shī hù zhào de quán guò chéng。','Tiếp theo hãy mô tả chi tiết toàn bộ lộ trình di chuyển hôm nay, từ lúc ra khỏi nhà cho đến lúc phát hiện mất hộ chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_05','V369','阮明',5,'中午十二点从学校宿舍出发，先去街边小吃店吃饭，下午两点抵达中心商业街。','zhōng wǔ shí èr diǎn cóng xué xiào sù shè chū fā， xiān qù jiē biān xiǎo chī diàn chī fàn， xià wǔ liǎng diǎn dǐ dá zhōng xīn shāng yè jiē。','12 giờ trưa tôi xuất phát từ ký túc xá của trường, trước tiên ghé quán ăn vặt ven đường để ăn, 2 giờ chiều thì đến khu phố thương mại trung tâm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_06','V369','民警',6,'商业街范围很大，精确回忆遗失护照的时间段和具体店铺名称吧。','shāng yè jiē fàn wéi hěn dà， jīng què huí yì yí shī hù zhào de shí jiān duàn hé jù tǐ diàn pù míng chēng ba。','Khu phố thương mại rất rộng, bạn cố nhớ chính xác khoảng thời gian mất hộ chiếu và tên cửa hàng cụ thể nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_07','V369','阮明',7,'下午三点左右，在商业街二楼文具店结账付款，走出店铺口袋就空了，护照不见了呢。','xià wǔ sān diǎn zuǒ yòu， zài shāng yè jiē èr lóu wén jù diàn jié zhàng fù kuǎn， zǒu chū diàn pù kǒu dài jiù kōng le， hù zhào bú jiàn le ne。','Khoảng 3 giờ chiều, tôi thanh toán ở một cửa hàng văn phòng phẩm trên tầng 2 khu thương mại, vừa bước ra khỏi cửa thì túi đã trống rồi, hộ chiếu biến mất luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_08','V369','民警',8,'遗失之后你有没有原路返回店铺寻找，或者向店内店员求助查看监控？','yí shī zhī hòu nǐ yǒu méi yǒu yuán lù fǎn huí diàn pù xún zhǎo， huò zhě xiàng diàn nèi diàn yuán qiú zhù chá kàn jiān kòng？','Sau đó bạn có quay lại cửa hàng để tìm không, hoặc nhờ nhân viên trong cửa hàng kiểm tra camera giám sát chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_09','V369','阮明',9,'我返回文具店询问店员，他们柜台没有捡到护照，商铺监控只能由派出所出具证明才能调取。','wǒ fǎn huí wén jù diàn xún wèn diàn yuán， tā men guì tái méi yǒu jiǎn dào hù zhào， shāng pù jiān kòng zhǐ néng yóu pài chū suǒ chū jù zhèng míng cái néng diào qǔ。','Tôi có quay lại cửa hàng văn phòng phẩm hỏi nhân viên, quầy của họ không nhặt được hộ chiếu, còn camera giám sát của cửa hàng thì phải có giấy xác nhận của đồn công an mới được trích xuất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_10','V369','民警',10,'我现在为你制作一份标准遗失报案记录，需要你填写国籍、护照编号、在校信息。','wǒ xiàn zài wèi nǐ zhì zuò yī fèn biāo zhǔn yí shī bào àn jì lù， xū yào nǐ tián xiě guó jí、 hù zhào biān hào、 zài xiào xìn xī。','Bây giờ tôi sẽ lập một biên bản trình báo mất đồ theo mẫu chuẩn cho bạn, cần bạn điền quốc tịch, số hộ chiếu, và thông tin trường đang học.',NULL) ON CONFLICT DO NOTHING;
